import{_ as r,C as i,o as l,c as h,j as t,a as o,G as n,aj as a}from"./chunks/framework.BwH0p-pt.js";const w=JSON.parse('{"title":"Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/configuration/webhooks.md","filePath":"3.0/configuration/webhooks.md","lastUpdated":1788942616000}'),d={name:"3.0/configuration/webhooks.md"};function g(c,e,u,m,p,b){const s=i("ImagePopup");return l(),h("div",null,[e[0]||(e[0]=t("h1",{id:"webhooks",tabindex:"-1"},[o("Webhooks "),t("a",{class:"header-anchor",href:"#webhooks","aria-label":'Permalink to "Webhooks"'},"​")],-1)),e[1]||(e[1]=t("p",null,'Webhooks let UnoPim notify your other systems the moment product data changes. Instead of another system asking UnoPim "has anything changed?" over and over, UnoPim sends a message to a web address you choose, right when the change happens — for example to an online store, an ERP, or a marketplace connector.',-1)),e[2]||(e[2]=t("p",null,[o("In UnoPim 3.0 you can create "),t("strong",null,"as many webhooks as you need"),o(". Each webhook has its own destination address, its own list of events it listens to, and its own delivery log.")],-1)),e[3]||(e[3]=t("p",null,[o("You find them under "),t("strong",null,"Configuration → Webhooks"),o(" in the admin sidebar.")],-1)),n(s,{src:"/assets/3.0/images/configuration/webhooks-list.png",alt:"The Webhooks list showing several webhooks with their URL, events and status"}),e[4]||(e[4]=a('<div class="tip custom-block"><p class="custom-block-title">Upgrading from an earlier version?</p><p>If you configured the single webhook that existed before 3.0, you do not have to set anything up again. Your old settings were moved over automatically during the upgrade and now appear as a webhook named <strong>Default</strong> in the list.</p></div><h2 id="create-a-webhook" tabindex="-1">Create a webhook <a class="header-anchor" href="#create-a-webhook" aria-label="Permalink to &quot;Create a webhook&quot;">​</a></h2><ol><li>Go to <strong>Configuration → Webhooks</strong>.</li><li>Click <strong>Create Webhook</strong>. A small window opens.</li><li>Enter a <strong>Name</strong> — something your team will recognise, like &quot;Online store&quot; or &quot;ERP sync&quot;.</li><li>Enter the <strong>URL</strong> — the web address of the system that should receive the messages. Ask the team that runs that system for it.</li><li>Pick the <strong>Events</strong> the webhook should listen to, for example <strong>Product Created</strong> and <strong>Product Updated</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>That is all a webhook needs to start working. You can refine it any time by opening it from the list.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Not sure what your receiving system will get? Point a test webhook at a free inspection service such as <a href="https://webhook.site" target="_blank" rel="noreferrer">webhook.site</a> and save a product — you will see exactly what UnoPim sends.</p></div><h2 id="fine-tune-a-webhook" tabindex="-1">Fine-tune a webhook <a class="header-anchor" href="#fine-tune-a-webhook" aria-label="Permalink to &quot;Fine-tune a webhook&quot;">​</a></h2><p>Open a webhook from the list to reach its edit page. Besides the name, URL and events, you can set:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Active</strong></td><td>Turns the webhook on or off. Switch it off to pause deliveries — for example while the receiving system is under maintenance. Everything else is kept, so you can switch it back on later.</td></tr><tr><td><strong>Signing Secret</strong></td><td>A secret your receiving system uses to verify the message really came from UnoPim. Share it only with the team that runs the receiving system. Once saved, the page shows &quot;A secret is already set&quot; — leave the field blank to keep it.</td></tr><tr><td><strong>Custom Headers</strong></td><td>Extra information sent with every message, if the receiving system asks for it (for example an access key it expects).</td></tr><tr><td><strong>Test Connection</strong></td><td>Click <strong>Send Test</strong> to check the URL is reachable before you rely on it.</td></tr></tbody></table>',8)),n(s,{src:"/assets/3.0/images/configuration/webhook-edit.png",alt:"Editing a webhook: name, URL, events, signing secret and settings"}),e[5]||(e[5]=a('<h2 id="delivery-logs" tabindex="-1">Delivery logs <a class="header-anchor" href="#delivery-logs" aria-label="Permalink to &quot;Delivery logs&quot;">​</a></h2><p>Every message UnoPim sends is recorded. Click <strong>Logs</strong> on the Webhooks page to see all deliveries, or open a specific webhook to see only its own.</p><p>Each log entry shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Webhook</strong></td><td>Which webhook sent the message</td></tr><tr><td><strong>Event</strong></td><td>What triggered it, for example Product Updated</td></tr><tr><td><strong>SKU</strong></td><td>The product concerned</td></tr><tr><td><strong>Date/Time</strong></td><td>When it was sent</td></tr><tr><td><strong>User</strong></td><td>Whose change triggered it</td></tr><tr><td><strong>Status</strong></td><td>Whether the delivery worked: <strong>Success</strong>, <strong>Failed</strong>, <strong>Server Error</strong> or <strong>Timeout/Error</strong></td></tr></tbody></table><p>Use the grid&#39;s search and <strong>Filter</strong> controls to narrow the list — for example, only failed deliveries for one webhook since yesterday.</p><p>Click the eye icon on a log entry to open <strong>Webhook Log Details</strong>. There you can inspect the <strong>Sent Payload</strong> (exactly what UnoPim sent) and the <strong>Response</strong> (what the receiving system answered). This is usually all your technical team needs to work out why a delivery failed.</p>',6)),n(s,{src:"/assets/3.0/images/configuration/webhook-logs.png",alt:"Webhook delivery logs with status, event and filters"}),e[6]||(e[6]=a('<div class="warning custom-block"><p class="custom-block-title">Deliveries run in the background</p><p>Webhook messages are sent by UnoPim&#39;s background workers, not while you wait. If the Logs page stays empty even though products are being saved, ask your technical team to check that the background workers are running.</p></div><h2 id="automatic-log-cleanup" tabindex="-1">Automatic log cleanup <a class="header-anchor" href="#automatic-log-cleanup" aria-label="Permalink to &quot;Automatic log cleanup&quot;">​</a></h2><p>Delivery logs do not pile up forever. UnoPim automatically removes log entries older than 30 days. Your technical team can change how long logs are kept, or turn the cleanup off entirely.</p><h2 id="who-can-manage-webhooks" tabindex="-1">Who can manage webhooks <a class="header-anchor" href="#who-can-manage-webhooks" aria-label="Permalink to &quot;Who can manage webhooks&quot;">​</a></h2><p>Access is controlled through roles, just like the rest of UnoPim. In <strong>Settings → Roles</strong>, a role can be granted:</p><ul><li><strong>Webhook</strong> — see the webhook list, plus <strong>Create</strong>, <strong>Edit</strong> and <strong>Delete</strong> rights individually.</li><li><strong>Logs</strong> — view delivery logs, open their details, and delete them.</li></ul><p>So you can, for example, let a support team read the logs without letting them change any webhook.</p>',7))])}const y=r(d,[["render",g]]);export{w as __pageData,y as default};
